-- =====================================================================================
-- Migration 002: the Review II incident-response model inside the application database.
--
-- Generated by backend/db/tools/build_migration_002.py from backend/db/review2/*.sql.
-- Additive and idempotent: it can be applied twice, and also runs under psql when the
-- PostgreSQL container initialises a new volume (docker-entrypoint-initdb.d).
--
-- Placement: tables, constraints, functions, procedures, triggers and the view keep their
-- Review II names and live in schema "response". "users" is NOT duplicated: every users(id)
-- reference resolves to public.users, which gains a generated account_type column that maps
-- the application roles onto the four Review II account types.
-- =====================================================================================
SET client_min_messages = warning;

CREATE TABLE IF NOT EXISTS public.schema_migrations (
  version     TEXT PRIMARY KEY,
  description TEXT NOT NULL,
  applied_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---- public.users: one additive, derived column (decision D3 in docs/review3/PLAN.md) ----
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS account_type VARCHAR(15)
  GENERATED ALWAYS AS (CASE role WHEN 'admin' THEN 'ADMINISTRATOR'
                                 WHEN 'official' THEN 'COORDINATOR'
                                 WHEN 'responder' THEN 'UNIT_LEAD'
                                 ELSE 'CITIZEN' END) STORED;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ck_users_account_type'
                    AND conrelid = 'public.users'::regclass) THEN
    ALTER TABLE public.users ADD CONSTRAINT ck_users_account_type
      CHECK (account_type IN ('CITIZEN', 'COORDINATOR', 'UNIT_LEAD', 'ADMINISTRATOR'));
  END IF;
END $$;

CREATE SCHEMA IF NOT EXISTS response;
COMMENT ON SCHEMA response IS 'Review II incident-response model (DMERS, BCSE302L)';
SET search_path = response, public;

-- ---- Review II 01_schema.sql (users omitted: see header) ----
-- =====================================================================================
-- DMERS Incident-Response Database | BCSE302L Review II
-- 01_schema.sql : eight relations of the Review I design with all keys and constraints
-- PostgreSQL 16. Constraint names: pk_ primary key, fk_ foreign key, uq_ unique, ck_ check.
-- =====================================================================================

CREATE TABLE IF NOT EXISTS zones (
  id            INTEGER GENERATED ALWAYS AS IDENTITY
                CONSTRAINT pk_zones PRIMARY KEY,
  zone_name     VARCHAR(60) NOT NULL
                CONSTRAINT uq_zones_name UNIQUE,
  district      VARCHAR(60) NOT NULL,
  state         VARCHAR(60) NOT NULL DEFAULT 'Tamil Nadu',
  risk_level    VARCHAR(6) NOT NULL
    CONSTRAINT ck_zones_risk_level
      CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH'))
);

CREATE TABLE IF NOT EXISTS incidents (
  id            INTEGER GENERATED ALWAYS AS IDENTITY
                CONSTRAINT pk_incidents PRIMARY KEY,
  title         VARCHAR(120) NOT NULL,
  description   TEXT,
  incident_type VARCHAR(30) NOT NULL,
  severity      VARCHAR(8) NOT NULL DEFAULT 'MODERATE'
    CONSTRAINT ck_incidents_severity CHECK (severity
      IN ('LOW', 'MODERATE', 'HIGH', 'CRITICAL')),
  status        VARCHAR(10) NOT NULL DEFAULT 'REPORTED'
    CONSTRAINT ck_incidents_status CHECK (status
      IN ('REPORTED', 'VERIFIED', 'RESPONDING',
          'RESOLVED', 'CLOSED', 'REJECTED')),
  location      VARCHAR(150) NOT NULL,
  zone_id       INTEGER           -- NULL until verified
    CONSTRAINT fk_incidents_zone
      REFERENCES zones (id) ON DELETE RESTRICT,
  reported_by   INTEGER NOT NULL
    CONSTRAINT fk_incidents_reporter
      REFERENCES users (id) ON DELETE RESTRICT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_incidents_zone_when_verified   -- FR-05
    CHECK (status IN ('REPORTED', 'REJECTED')
           OR zone_id IS NOT NULL),
  CONSTRAINT ck_incidents_timestamps
    CHECK (updated_at >= created_at)
);

CREATE TABLE IF NOT EXISTS response_units (
  id            INTEGER GENERATED ALWAYS AS IDENTITY
                CONSTRAINT pk_response_units PRIMARY KEY,
  unit_name     VARCHAR(60) NOT NULL
                CONSTRAINT uq_units_name UNIQUE,
  unit_type     VARCHAR(10) NOT NULL
    CONSTRAINT ck_units_type CHECK (unit_type IN
      ('FIRE', 'MEDICAL', 'POLICE', 'RESCUE', 'RELIEF')),
  contact_phone VARCHAR(10) NOT NULL
    CONSTRAINT ck_units_phone
      CHECK (contact_phone ~ '^[6-9][0-9]{9}$'),
  personnel_count SMALLINT NOT NULL
    CONSTRAINT ck_units_personnel
      CHECK (personnel_count > 0),
  availability_status VARCHAR(10) NOT NULL
    DEFAULT 'AVAILABLE'
    CONSTRAINT ck_units_availability
      CHECK (availability_status IN
        ('AVAILABLE', 'DEPLOYED', 'OFF_DUTY')),
  zone_id       INTEGER NOT NULL    -- total in BASED_IN
    CONSTRAINT fk_units_zone
      REFERENCES zones (id) ON DELETE RESTRICT,
  lead_user_id  INTEGER             -- optional 1:1 LEADS
    CONSTRAINT uq_units_lead UNIQUE
    CONSTRAINT fk_units_lead
      REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS resources (
  id            INTEGER GENERATED ALWAYS AS IDENTITY
                CONSTRAINT pk_resources PRIMARY KEY,
  resource_name VARCHAR(60) NOT NULL
                CONSTRAINT uq_resources_name UNIQUE,
  category      VARCHAR(10) NOT NULL
    CONSTRAINT ck_resources_category CHECK (category IN
      ('FOOD', 'WATER', 'MEDICAL', 'SHELTER',
       'EQUIPMENT')),
  unit_of_measure VARCHAR(20) NOT NULL,
  quantity_available INTEGER NOT NULL DEFAULT 0
    CONSTRAINT ck_resources_quantity
      CHECK (quantity_available >= 0),
  reorder_level INTEGER NOT NULL DEFAULT 0
    CONSTRAINT ck_resources_reorder
      CHECK (reorder_level >= 0)
);

CREATE TABLE IF NOT EXISTS incident_updates (    -- weak INCIDENT_UPDATE
  incident_id   INTEGER NOT NULL
    CONSTRAINT fk_updates_incident
      REFERENCES incidents (id) ON DELETE CASCADE,
  update_no     INTEGER NOT NULL       -- partial key
    CONSTRAINT ck_updates_no CHECK (update_no >= 1),
  previous_status VARCHAR(10)
    CONSTRAINT ck_updates_previous_status
      CHECK (previous_status IN ('REPORTED', 'VERIFIED',
        'RESPONDING', 'RESOLVED', 'CLOSED', 'REJECTED')),
  new_status    VARCHAR(10) NOT NULL
    CONSTRAINT ck_updates_new_status
      CHECK (new_status IN ('REPORTED', 'VERIFIED',
        'RESPONDING', 'RESOLVED', 'CLOSED', 'REJECTED')),
  note          VARCHAR(200),
  logged_by     INTEGER         -- NULL: no signed-in user
    CONSTRAINT fk_updates_author
      REFERENCES users (id) ON DELETE RESTRICT,
  logged_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_incident_updates
    PRIMARY KEY (incident_id, update_no),
  CONSTRAINT ck_updates_first_entry
    CHECK ((update_no = 1) = (previous_status IS NULL))
);

CREATE TABLE IF NOT EXISTS dispatches (  -- ternary DISPATCHED_TO, M:N:1
  incident_id   INTEGER NOT NULL
    CONSTRAINT fk_dispatches_incident
      REFERENCES incidents (id) ON DELETE RESTRICT,
  unit_id       INTEGER NOT NULL
    CONSTRAINT fk_dispatches_unit
      REFERENCES response_units (id) ON DELETE RESTRICT,
  dispatched_by INTEGER NOT NULL  -- authorising official
    CONSTRAINT fk_dispatches_coordinator
      REFERENCES users (id) ON DELETE RESTRICT,
  dispatch_status VARCHAR(10) NOT NULL DEFAULT 'ASSIGNED'
    CONSTRAINT ck_dispatches_status
      CHECK (dispatch_status IN ('ASSIGNED', 'EN_ROUTE',
        'ON_SCENE', 'COMPLETED', 'CANCELLED')),
  dispatched_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  arrived_at    TIMESTAMPTZ,
  cleared_at    TIMESTAMPTZ,
  CONSTRAINT pk_dispatches
    PRIMARY KEY (incident_id, unit_id),
  CONSTRAINT ck_dispatches_arrival               -- BR-06
    CHECK (arrived_at >= dispatched_at),
  CONSTRAINT ck_dispatches_clearance
    CHECK (cleared_at >=
           coalesce(arrived_at, dispatched_at)),
  CONSTRAINT ck_dispatches_arrived_on_scene
    CHECK (dispatch_status NOT IN ('ON_SCENE','COMPLETED')
           OR arrived_at IS NOT NULL),
  CONSTRAINT ck_dispatches_cleared_when_closed
    CHECK ((dispatch_status IN ('COMPLETED', 'CANCELLED'))
           = (cleared_at IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS resource_allocations (       -- M:N ALLOCATED
  incident_id   INTEGER NOT NULL
    CONSTRAINT fk_allocations_incident
      REFERENCES incidents (id) ON DELETE RESTRICT,
  resource_id   INTEGER NOT NULL
    CONSTRAINT fk_allocations_resource
      REFERENCES resources (id) ON DELETE RESTRICT,
  quantity      INTEGER NOT NULL
    CONSTRAINT ck_allocations_quantity
      CHECK (quantity > 0),
  allocated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_resource_allocations
    PRIMARY KEY (incident_id, resource_id)
);

-- BR-05 backstop: at most one active dispatch per unit
CREATE UNIQUE INDEX IF NOT EXISTS uq_dispatches_one_active_per_unit
  ON dispatches (unit_id)
  WHERE dispatch_status IN ('ASSIGNED', 'EN_ROUTE',
                            'ON_SCENE');

-- Indexes on foreign keys and the most frequent filter
CREATE INDEX IF NOT EXISTS ix_incidents_status_zone
  ON incidents (status, zone_id);
CREATE INDEX IF NOT EXISTS ix_incidents_reported_by
  ON incidents (reported_by);
CREATE INDEX IF NOT EXISTS ix_units_zone ON response_units (zone_id);
CREATE INDEX IF NOT EXISTS ix_dispatches_unit ON dispatches (unit_id);
CREATE INDEX IF NOT EXISTS ix_allocations_resource
  ON resource_allocations (resource_id);

-- ---- Review II 02_plpgsql.sql: 3 functions, 2 procedures, 5 triggers ----
-- =====================================================================================
-- DMERS Incident-Response Database | BCSE302L Review II
-- 02_plpgsql.sql : functions, procedures (one with an explicit cursor) and triggers.
-- Created before the data load so that every seeded row passes through the same rules.
-- Session settings read by the triggers (set by the procedures or by the application):
--   dmers.actor_id  id of the official making the change (author of timeline entries)
--   dmers.note      optional text stored with the next timeline entry
-- =====================================================================================

-- -------------------------------------------------------
-- [F1] fn_stock_status: derived stock_status (BR-10)
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_stock_status(
    p_resource_id INTEGER)
RETURNS VARCHAR LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_qty INTEGER;  v_reorder INTEGER;
BEGIN
  SELECT quantity_available, reorder_level
    INTO v_qty, v_reorder
    FROM resources WHERE id = p_resource_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Resource % does not exist',
                    p_resource_id;
  END IF;
  RETURN CASE WHEN v_qty = 0 THEN 'OUT_OF_STOCK'
              WHEN v_qty <= v_reorder THEN 'LOW'
              ELSE 'ADEQUATE' END;
END $$;
ALTER FUNCTION fn_stock_status(INTEGER) SET search_path = response, public;

-- -------------------------------------------------------
-- [F2] fn_active_incidents: derived active_incidents
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_active_incidents(
    p_zone_id INTEGER)
RETURNS INTEGER LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_count INTEGER;
BEGIN
  SELECT count(*) INTO v_count FROM incidents
  WHERE zone_id = p_zone_id
    AND status IN ('VERIFIED', 'RESPONDING');
  RETURN v_count;
END $$;
ALTER FUNCTION fn_active_incidents(INTEGER) SET search_path = response, public;

-- -------------------------------------------------------
-- [F3] fn_response_minutes: report to first arrival
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_response_minutes(
    p_incident_id INTEGER)
RETURNS NUMERIC LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_reported TIMESTAMPTZ;  v_arrival TIMESTAMPTZ;
BEGIN
  SELECT created_at INTO v_reported
    FROM incidents WHERE id = p_incident_id;
  SELECT min(arrived_at) INTO v_arrival
    FROM dispatches WHERE incident_id = p_incident_id;
  IF v_reported IS NULL OR v_arrival IS NULL THEN
    RETURN NULL;          -- unknown, or no unit on scene
  END IF;
  RETURN round(extract(epoch FROM v_arrival - v_reported)
               / 60, 1);
END $$;
ALTER FUNCTION fn_response_minutes(INTEGER) SET search_path = response, public;

-- -------------------------------------------------------
-- [P1] sp_dispatch_unit: dispatch a unit (FR-07)
-- -------------------------------------------------------
CREATE OR REPLACE PROCEDURE sp_dispatch_unit(
    p_incident_id INTEGER, p_unit_id INTEGER,
    p_coordinator_id INTEGER)
LANGUAGE plpgsql AS $$
DECLARE
  v_role   users.account_type%TYPE;
  v_status incidents.status%TYPE;
  v_unit   response_units.unit_name%TYPE;
BEGIN
  SELECT account_type INTO v_role
    FROM users WHERE id = p_coordinator_id;
  IF v_role IS DISTINCT FROM 'COORDINATOR' THEN
    RAISE EXCEPTION       -- only coordinators (FR-07)
      'User % is not authorised to dispatch units',
      p_coordinator_id;
  END IF;
  -- author recorded by the timeline trigger T1
  PERFORM set_config('dmers.actor_id',
                     p_coordinator_id::TEXT, true);

  -- trigger T3 checks BR-05 on this INSERT
  INSERT INTO dispatches (incident_id, unit_id,
                          dispatched_by)
  VALUES (p_incident_id, p_unit_id, p_coordinator_id);
  UPDATE response_units
     SET availability_status = 'DEPLOYED'
   WHERE id = p_unit_id RETURNING unit_name INTO v_unit;

  SELECT status INTO v_status
    FROM incidents WHERE id = p_incident_id;
  IF v_status = 'VERIFIED' THEN      -- first unit sent
    UPDATE incidents SET status = 'RESPONDING'
     WHERE id = p_incident_id;
  END IF;
  RAISE NOTICE 'Unit % (%) dispatched to incident % '
    'by user %', p_unit_id, v_unit, p_incident_id,
    p_coordinator_id;
END $$;
ALTER PROCEDURE sp_dispatch_unit(INTEGER, INTEGER, INTEGER) SET search_path = response, public;

-- -------------------------------------------------------
-- [P2] sp_close_incident: cursor releases units (FR-11)
-- -------------------------------------------------------
CREATE OR REPLACE PROCEDURE sp_close_incident(
    p_incident_id INTEGER, p_coordinator_id INTEGER,
    p_note VARCHAR DEFAULT NULL)
LANGUAGE plpgsql AS $$
DECLARE
  c_open CURSOR FOR       -- active dispatches of incident
    SELECT unit_id, dispatch_status FROM dispatches
     WHERE incident_id = p_incident_id
       AND dispatch_status IN ('ASSIGNED', 'EN_ROUTE',
                               'ON_SCENE')
     ORDER BY unit_id
       FOR UPDATE;
  r_disp     RECORD;
  v_status   incidents.status%TYPE;
  v_released INTEGER := 0;
BEGIN
  SELECT status INTO v_status FROM incidents
   WHERE id = p_incident_id FOR UPDATE;
  IF v_status IS NULL OR v_status NOT IN
     ('VERIFIED', 'RESPONDING', 'RESOLVED') THEN
    RAISE EXCEPTION
      'Incident % cannot be closed from status %',
      p_incident_id, coalesce(v_status, 'missing');
  END IF;
  PERFORM set_config('dmers.actor_id',
                     p_coordinator_id::TEXT, true);

  OPEN c_open;
  LOOP
    FETCH c_open INTO r_disp;
    EXIT WHEN NOT FOUND;
    UPDATE dispatches
       SET dispatch_status =
             CASE WHEN r_disp.dispatch_status = 'ON_SCENE'
                  THEN 'COMPLETED' ELSE 'CANCELLED' END,
           cleared_at = now()
     WHERE CURRENT OF c_open;
    UPDATE response_units
       SET availability_status = 'AVAILABLE'
     WHERE id = r_disp.unit_id;
    v_released := v_released + 1;
    RAISE NOTICE 'Unit % released (dispatch was %)',
      r_disp.unit_id, r_disp.dispatch_status;
  END LOOP;
  CLOSE c_open;

  IF v_status <> 'RESOLVED' THEN
    UPDATE incidents SET status = 'RESOLVED'
     WHERE id = p_incident_id;
  END IF;
  -- the closing note is stored with the CLOSED entry
  PERFORM set_config('dmers.note',
                     coalesce(p_note, ''), true);
  UPDATE incidents SET status = 'CLOSED'
   WHERE id = p_incident_id;
  PERFORM set_config('dmers.note', '', true);
  RAISE NOTICE 'Incident % closed; % unit(s) released',
    p_incident_id, v_released;
END $$;
ALTER PROCEDURE sp_close_incident(INTEGER, INTEGER, VARCHAR) SET search_path = response, public;

-- -------------------------------------------------------
-- [T1] timeline of status changes (FR-03, BR-08)
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_fn_incident_timeline()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  v_note  TEXT := nullif(current_setting('dmers.note',
                                         true), '');
  v_actor TEXT := nullif(current_setting('dmers.actor_id',
                                         true), '');
BEGIN
  IF TG_OP = 'INSERT' THEN          -- entry 1: the report
    INSERT INTO incident_updates (incident_id, update_no,
      new_status, note, logged_by, logged_at)
    VALUES (NEW.id, 1, NEW.status, 'Incident reported',
            NEW.reported_by, NEW.created_at);
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO incident_updates (incident_id, update_no,
      previous_status, new_status, note, logged_by,
      logged_at)
    SELECT NEW.id, coalesce(max(update_no), 0) + 1,
      OLD.status, NEW.status,
      coalesce(v_note, 'Status set to ' || NEW.status),
      v_actor::INTEGER, NEW.updated_at
      FROM incident_updates WHERE incident_id = NEW.id;
  END IF;                   -- unchanged status: no entry
  RETURN NULL;             -- ignored in an AFTER trigger
END $$;
ALTER FUNCTION trg_fn_incident_timeline() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_incidents_timeline
AFTER INSERT OR UPDATE OF status ON incidents
FOR EACH ROW EXECUTE FUNCTION trg_fn_incident_timeline();

-- -------------------------------------------------------
-- [T2] maintains incidents.updated_at
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_fn_touch_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.updated_at = OLD.updated_at THEN  -- not supplied
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END $$;
ALTER FUNCTION trg_fn_touch_updated_at() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_incidents_touch
BEFORE UPDATE ON incidents
FOR EACH ROW EXECUTE FUNCTION trg_fn_touch_updated_at();

-- -------------------------------------------------------
-- [T3] dispatch guard (BR-05)
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_fn_dispatch_guard()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  v_unit_state response_units.availability_status%TYPE;
  v_incident   incidents.status%TYPE;
BEGIN
  SELECT availability_status INTO v_unit_state
    FROM response_units WHERE id = NEW.unit_id
     FOR UPDATE;                     -- lock the unit row
  IF v_unit_state IS DISTINCT FROM 'AVAILABLE' THEN
    RAISE EXCEPTION 'Unit % is %, not AVAILABLE',
      NEW.unit_id, coalesce(v_unit_state, 'missing');
  END IF;
  SELECT status INTO v_incident
    FROM incidents WHERE id = NEW.incident_id;
  IF v_incident IS NULL
     OR v_incident NOT IN ('VERIFIED', 'RESPONDING') THEN
    RAISE EXCEPTION 'Incident % is %; only VERIFIED or '
      'RESPONDING incidents receive units',
      NEW.incident_id, coalesce(v_incident, 'missing');
  END IF;
  RETURN NEW;
END $$;
ALTER FUNCTION trg_fn_dispatch_guard() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_dispatches_guard
BEFORE INSERT ON dispatches
FOR EACH ROW EXECUTE FUNCTION trg_fn_dispatch_guard();

-- -------------------------------------------------------
-- [T4] stock movement and timeline note (FR-10, BR-07)
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_fn_allocation_stock()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  v_delta INTEGER;  v_iid INTEGER;  v_rid INTEGER;
  v_left  INTEGER;  v_next INTEGER;
  v_item   resources.resource_name%TYPE;
  v_status incidents.status%TYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN    -- withdrawn: stock returns
    v_delta := -OLD.quantity;
    v_iid := OLD.incident_id;  v_rid := OLD.resource_id;
  ELSE                       -- new allocation or increase
    v_delta := NEW.quantity - CASE TG_OP
      WHEN 'UPDATE' THEN OLD.quantity ELSE 0 END;
    v_iid := NEW.incident_id;  v_rid := NEW.resource_id;
  END IF;
  IF v_delta = 0 THEN RETURN NULL; END IF;
  UPDATE resources
     SET quantity_available = quantity_available - v_delta
   WHERE id = v_rid AND quantity_available >= v_delta
  RETURNING quantity_available, resource_name
       INTO v_left, v_item;
  IF NOT FOUND THEN
    SELECT quantity_available INTO v_left
      FROM resources WHERE id = v_rid;
    RAISE EXCEPTION 'Insufficient stock for resource %: '
      'requested %, available %', v_rid, v_delta, v_left;
  END IF;
  -- lock the incident so timeline numbers stay unique
  SELECT status INTO v_status FROM incidents
   WHERE id = v_iid FOR UPDATE;
  SELECT coalesce(max(update_no), 0) + 1 INTO v_next
    FROM incident_updates WHERE incident_id = v_iid;
  INSERT INTO incident_updates (incident_id, update_no,
    previous_status, new_status, note, logged_by,
    logged_at)
  VALUES (v_iid, v_next, v_status, v_status,
    CASE WHEN v_delta > 0 THEN 'Allocated '
         ELSE 'Returned ' END
      || abs(v_delta) || ' ' || v_item,
    nullif(current_setting('dmers.actor_id', true),
           '')::INTEGER,
    CASE WHEN TG_OP = 'DELETE' THEN now()
         ELSE NEW.allocated_at END);
  RETURN NULL;
END $$;
ALTER FUNCTION trg_fn_allocation_stock() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_allocations_stock
AFTER INSERT OR UPDATE OF quantity OR DELETE
ON resource_allocations
FOR EACH ROW EXECUTE FUNCTION trg_fn_allocation_stock();

-- -------------------------------------------------------
-- [T5] append-only timeline (BR-08)
-- -------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_fn_timeline_append_only()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;     -- cascade from DELETE on incidents
  END IF;
  RAISE EXCEPTION 'Timeline entries are append-only '
    '(incident %, update %)', OLD.incident_id,
    OLD.update_no;
END $$;
ALTER FUNCTION trg_fn_timeline_append_only() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_incident_updates_append_only
BEFORE UPDATE OR DELETE ON incident_updates
FOR EACH ROW
EXECUTE FUNCTION trg_fn_timeline_append_only();

-- ---- Review II 05_queries.sql, Q15: view over zones, units and fn_active_incidents ----
CREATE OR REPLACE VIEW v_zone_situation AS
SELECT z.zone_name, z.risk_level,
       fn_active_incidents(z.id) AS active_incidents,
       (SELECT count(*) FROM response_units r
        WHERE r.zone_id = z.id
          AND r.availability_status = 'AVAILABLE')
         AS units_available
FROM zones z;

-- =====================================================================================
-- Review III additions (rules that Review II left to the application; see PLAN.md, D7)
-- =====================================================================================

-- [R3-1] status transitions are legal only along the incident life cycle
CREATE OR REPLACE FUNCTION trg_fn_incident_transition_guard()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'REPORTED'   AND NEW.status IN ('VERIFIED', 'REJECTED'))
    OR (OLD.status = 'VERIFIED'   AND NEW.status IN ('RESPONDING', 'RESOLVED', 'CLOSED'))
    OR (OLD.status = 'RESPONDING' AND NEW.status IN ('RESOLVED', 'CLOSED'))
    OR (OLD.status = 'RESOLVED'   AND NEW.status = 'CLOSED')) THEN
    RAISE EXCEPTION 'Illegal status change % -> % for incident %',
      OLD.status, NEW.status, OLD.id;
  END IF;
  RETURN NEW;
END $$;
ALTER FUNCTION trg_fn_incident_transition_guard() SET search_path = response, public;

CREATE OR REPLACE TRIGGER trg_incidents_transition_guard
BEFORE UPDATE OF status ON incidents
FOR EACH ROW EXECUTE FUNCTION trg_fn_incident_transition_guard();

-- [R3-2] only the lead of a unit records its dispatch progress; the unit is freed on completion
CREATE OR REPLACE PROCEDURE sp_update_dispatch(
    p_incident_id INTEGER, p_unit_id INTEGER,
    p_user_id INTEGER, p_new_status VARCHAR)
LANGUAGE plpgsql AS $$
DECLARE
  v_lead INTEGER;
  v_unit response_units.unit_name%TYPE;
  v_cur  dispatches.dispatch_status%TYPE;
BEGIN
  SELECT lead_user_id, unit_name INTO v_lead, v_unit
    FROM response_units WHERE id = p_unit_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unit % does not exist', p_unit_id;
  END IF;
  IF v_lead IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'User % is not the lead of unit % (%)',
      p_user_id, p_unit_id, v_unit;
  END IF;
  SELECT dispatch_status INTO v_cur FROM dispatches
   WHERE incident_id = p_incident_id AND unit_id = p_unit_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unit % has no dispatch to incident %',
      p_unit_id, p_incident_id;
  END IF;
  IF NOT ((v_cur = 'ASSIGNED' AND p_new_status = 'EN_ROUTE')
       OR (v_cur = 'EN_ROUTE' AND p_new_status = 'ON_SCENE')
       OR (v_cur = 'ON_SCENE' AND p_new_status = 'COMPLETED')) THEN
    RAISE EXCEPTION 'Dispatch cannot move from % to %', v_cur, p_new_status;
  END IF;
  PERFORM set_config('dmers.actor_id', p_user_id::TEXT, true);
  IF p_new_status = 'EN_ROUTE' THEN
    UPDATE dispatches SET dispatch_status = 'EN_ROUTE'
     WHERE incident_id = p_incident_id AND unit_id = p_unit_id;
  ELSIF p_new_status = 'ON_SCENE' THEN
    UPDATE dispatches SET dispatch_status = 'ON_SCENE', arrived_at = now()
     WHERE incident_id = p_incident_id AND unit_id = p_unit_id;
  ELSE
    UPDATE dispatches SET dispatch_status = 'COMPLETED', cleared_at = now()
     WHERE incident_id = p_incident_id AND unit_id = p_unit_id;
    UPDATE response_units SET availability_status = 'AVAILABLE'
     WHERE id = p_unit_id;
  END IF;
  RAISE NOTICE 'Unit % (%) is now % at incident %',
    p_unit_id, v_unit, p_new_status, p_incident_id;
END $$;
ALTER PROCEDURE sp_update_dispatch(INTEGER, INTEGER, INTEGER, VARCHAR)
  SET search_path = response, public;

